import Foundation
import XCTest
@testable import PultIR

/// testdata/ir_vectors.json (generated by tools/gen_ir_vectors.py).
struct IRVectors: Decodable {
    struct SIRCEntry: Decodable {
        let key: String
        let bits: Int
        let device: UInt32
        let command: UInt32
        let value: String
    }

    struct SignalEntry: Decodable {
        let name: String
        let carrierHz: Int
        let dutyPct: Int
        let minRepeats: Int
        let intro: [Int]
        let `repeat`: [Int]
        let table: [Int]
        let blobHex: String
        let playHex: [String]
        let playHexMtu23: [String]

        var signal: IRSignal {
            IRSignal(carrierHz: carrierHz, dutyPercent: dutyPct, intro: intro, repeat: self.repeat,
                     minRepeats: minRepeats)
        }
    }

    struct Hold: Decodable {
        struct Example: Decodable {
            let repeatUnitUs: Int
            let count: Int
        }

        let examples: [Example]
    }

    let sirc: [SIRCEntry]
    let signals: [SignalEntry]
    let hold: Hold

    func signal(_ name: String) throws -> SignalEntry {
        try XCTUnwrap(signals.first { $0.name == name }, "no vector \(name)")
    }
}

/// Finds `testdata/ir_vectors.json` in the nearest directory above this file that has it.
func loadIRVectors() throws -> IRVectors {
    var directory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
    while true {
        let candidate = directory.appendingPathComponent("testdata/ir_vectors.json")
        if FileManager.default.fileExists(atPath: candidate.path) {
            let decoder = JSONDecoder()
            decoder.keyDecodingStrategy = .convertFromSnakeCase
            return try decoder.decode(IRVectors.self, from: Data(contentsOf: candidate))
        }
        let parent = directory.deletingLastPathComponent()
        guard parent.path != directory.path else {
            throw CocoaError(.fileNoSuchFile, userInfo: [NSFilePathErrorKey: "testdata/ir_vectors.json"])
        }
        directory = parent
    }
}

extension Data {
    init(hex: String) {
        var bytes: [UInt8] = []
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            bytes.append(UInt8(hex[index..<next], radix: 16)!)
            index = next
        }
        self.init(bytes)
    }

    var hex: String {
        map { ($0 < 16 ? "0" : "") + String($0, radix: 16) }.joined()
    }
}

/// SplitMix64, so that randomized tests are reproducible.
struct SeededGenerator: RandomNumberGenerator {
    private var state: UInt64

    init(seed: UInt64) { state = seed }

    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ z >> 30) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ z >> 27) &* 0x94D0_49BB_1331_11EB
        return z ^ z >> 31
    }
}

/// What a demodulating receiver does to a signal: random jitter of ±`jitter` on every duration, and marks
/// longer by `markShift` µs at the expense of the following space.
func distort(_ durations: [Int], jitter: Double, markShift: Int, using rng: inout SeededGenerator) -> [Int] {
    durations.enumerated().map { index, value in
        let scaled = Double(value) * (1 + Double.random(in: -jitter...jitter, using: &rng))
        return max(1, Int(scaled.rounded()) + (index % 2 == 0 ? markShift : -markShift))
    }
}

/// The distortions every decoder must survive.
let receiverDistortions: [(jitter: Double, markShift: Int)] = [(0, 0), (0.15, 0), (0, 80), (0.15, 80)]

/// Durations a bridge would capture for `frames` frames of a signal: intro once, then the repeat unit; the final
/// gap is not recorded (the capture ends on the silence).
func capture(_ signal: IRSignal, frames: Int) -> [Int] {
    let unit = signal.repeat.isEmpty ? signal.intro : signal.repeat
    let out = (0..<frames).flatMap { $0 == 0 && !signal.intro.isEmpty ? signal.intro : unit }
    return Array(out.dropLast())
}

/// Bits of a pulse-distance/width frame after a two-duration header, in transmission order.
func pulseBits(_ frame: [Int], count: Int, isOne: (_ mark: Int, _ space: Int) -> Bool) -> [Bool] {
    (0..<count).map { isOne(frame[2 + 2 * $0], frame[3 + 2 * $0]) }
}

/// Bits written in transmission order, first bit most significant (the "0x20DF10EF" notation).
func transmissionValue(_ bits: [Bool]) -> UInt64 {
    bits.reduce(0) { $0 << 1 | ($1 ? 1 : 0) }
}

/// Half-bit levels of a clean bi-phase frame without its gap; `true` is a mark.
func halfBits(_ frame: [Int], unit: Int) -> [Bool] {
    frame.dropLast().enumerated().flatMap { index, duration in
        Array(repeating: index % 2 == 0, count: (duration + unit / 2) / unit)
    }
}
